import re
def check(a):
    tail = a.split('Final answer:')[-1]
    n = [int(x) for x in re.findall(r'\d+', tail)]
    if len(n) != 5 or len(set(n)) != 5 or min(n) < 1:
        return False, 'need 5 distinct positive integers'
    s = sorted(n)
    if sum(n) != 30 or any(s[i + 1] - s[i] == 1 for i in range(4)):
        return False, 'sum or consecutive'
    p = 1
    for x in n:
        p *= x
    return p % 7 == 0, 'product'
